const bool isActiveLow = true; 
const int lightPins[] = {3, 4, 5, 6, 7};
const int startButtonPin = 2;

void setLight(int index, bool turnOn) {
  if (isActiveLow) {
    digitalWrite(lightPins[index], turnOn ? LOW : HIGH);
  } else {
    digitalWrite(lightPins[index], turnOn ? HIGH : LOW);
  }
}

void turnOffAllLights() {
  for (int i = 0; i < 5; i++) {
    setLight(i, false);
  }
}

void setup() {
  for (int i = 0; i < 5; i++) {
    pinMode(lightPins[i], OUTPUT);
  }
  turnOffAllLights();
  pinMode(startButtonPin, INPUT_PULLUP);
  randomSeed(analogRead(A0)); 
}

void loop() {
  if (digitalRead(startButtonPin) == LOW) {
    runStartingSequence();
    delay(5000);
    turnOffAllLights();
  }
}

void runStartingSequence() {
  turnOffAllLights();
  delay(1000);

  setLight(0, true);
  delay(1000);

  setLight(1, true);
  delay(1000);

  setLight(2, true);
  delay(random(1000, 3001));

  setLight(3, true);
  delay(random(1000, 3001));

  for (int i = 0; i < 4; i++) {
    setLight(i, false);
  }
  setLight(4, true);
}
